% Shared macros for the Evans "Partial Differential Equations" (2nd ed.) blueprint.
% Kept KaTeX-compatible (no fancy packages) to match the leanblueprint web build.

\newcommand{\R}{\mathbb{R}}
\newcommand{\C}{\mathbb{C}}
\newcommand{\Z}{\mathbb{Z}}
\newcommand{\N}{\mathbb{N}}
\newcommand{\Q}{\mathbb{Q}}
\newcommand{\eps}{\varepsilon}
\newcommand{\pd}[2]{\frac{\partial #1}{\partial #2}}
\newcommand{\Div}{\operatorname{div}}
\newcommand{\curl}{\operatorname{curl}}
\newcommand{\spt}{\operatorname{spt}}
\newcommand{\dist}{\operatorname{dist}}

% Added while transcribing chapters -- notation Evans uses that isn't covered above.
\newcommand{\rank}{\operatorname{rank}}
\newcommand{\sech}{\operatorname{sech}}
\newcommand{\CC}{\subset\subset} % "compactly contained in", e.g. $V \CC U$
\newcommand{\sgn}{\operatorname{sgn}}
\newcommand{\cof}{\operatorname{cof}} % cofactor matrix
\newcommand{\tr}{\operatorname{tr}} % matrix trace
\newcommand{\fint}{\mathop{\mathrlap{\raisebox{0.4ex}{$-$}}\int}} % slashed average-integral symbol; TODO-VERIFY rendering in the web build
